#include "stdlib/blas/base/ctrsm.h"
#include "stdlib/blas/base/ctrsm_fortran.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/complex/float32/ctor.h"

/**
* Solves one of the matrix equations `op(A)*X = alpha*B` or `X*op(A) = alpha*B`.
*
* @param order    storage layout
* @param side     specifies whether A appears on the left or right
* @param uplo     specifies whether upper or lower triangular part of A is used
* @param transA   transpose operation applied to A
* @param diag     specifies whether A is unit triangular
* @param M        number of rows in B
* @param N        number of columns in B
* @param alpha    scalar constant
* @param A        input triangular matrix
* @param LDA      leading dimension of A
* @param B        input/output matrix
* @param LDB      leading dimension of B
*/
void API_SUFFIX(c_ctrsm)( const CBLAS_LAYOUT order, const CBLAS_SIDE side, const CBLAS_UPLO uplo, const CBLAS_TRANSPOSE transA, const CBLAS_DIAG diag, const CBLAS_INT M, const CBLAS_INT N, const stdlib_complex64_t alpha, const void *A, const CBLAS_INT LDA, void *B, const CBLAS_INT LDB ) {
	char sideChar   = ( side == CblasLeft ) ? 'L' : 'R';
	char uploChar   = ( uplo == CblasUpper ) ? 'U' : 'L';
	char transChar  = ( transA == CblasNoTrans ) ? 'N' : ( transA == CblasTrans ) ? 'T' : 'C';
	char diagChar   = ( diag == CblasUnit ) ? 'U' : 'N';
	/* For column-major Fortran interface, swap M/N if row-major: */
	CBLAS_INT fm = ( order == CblasRowMajor ) ? N : M;
	CBLAS_INT fn = ( order == CblasRowMajor ) ? M : N;
	ctrsm( &sideChar, &uploChar, &transChar, &diagChar, &fm, &fn, (const void *)&alpha, A, &LDA, B, &LDB );
}

/**
* Solves one of the matrix equations `op(A)*X = alpha*B` or `X*op(A) = alpha*B`
* using alternative indexing semantics.
*
* @param order     storage layout
* @param side      specifies whether A appears on the left or right
* @param uplo      specifies whether upper or lower triangular part of A is used
* @param transA    transpose operation applied to A
* @param diag      specifies whether A is unit triangular
* @param M         number of rows in B
* @param N         number of columns in B
* @param alphaRe   real part of scalar constant
* @param alphaIm   imaginary part of scalar constant
* @param A         input triangular matrix
* @param strideA1  leading dimension stride of A
* @param offsetA   starting index for A
* @param B         input/output matrix
* @param strideB1  leading dimension stride of B
* @param offsetB   starting index for B
*/
void API_SUFFIX(c_ctrsm_ndarray)( const CBLAS_LAYOUT order, const CBLAS_SIDE side, const CBLAS_UPLO uplo, const CBLAS_TRANSPOSE transA, const CBLAS_DIAG diag, const CBLAS_INT M, const CBLAS_INT N, const float alphaRe, const float alphaIm, const void *A, const CBLAS_INT strideA1, const CBLAS_INT offsetA, void *B, const CBLAS_INT strideB1, const CBLAS_INT offsetB ) {
	stdlib_complex64_t alpha = stdlib_complex64( alphaRe, alphaIm );
	const float *abuf = (const float *)A + ( offsetA * 2 );
	float *bbuf = (float *)B + ( offsetB * 2 );
	char sideChar  = ( side == CblasLeft ) ? 'L' : 'R';
	char uploChar  = ( uplo == CblasUpper ) ? 'U' : 'L';
	char transChar = ( transA == CblasNoTrans ) ? 'N' : ( transA == CblasTrans ) ? 'T' : 'C';
	char diagChar  = ( diag == CblasUnit ) ? 'U' : 'N';
	CBLAS_INT fm = ( order == CblasRowMajor ) ? N : M;
	CBLAS_INT fn = ( order == CblasRowMajor ) ? M : N;
	ctrsm( &sideChar, &uploChar, &transChar, &diagChar, &fm, &fn, (const void *)&alpha, (const void *)abuf, &strideA1, (void *)bbuf, &strideB1 );
}
